-- Insert Quiz Questions for Lesson: Connect Registration to the CRM

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 23 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 23 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm23-connect-registration-crm' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m23-connect-registration-crm not found in module 23';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you use event-specific tags for repeat events?', 
    '["To prevent next month''s attendance from misrouting this month''s contacts","HighLevel requires event-specific tags by default","Event-specific tags look more professional","Generic tags work fine for all events"]'::jsonb,
    'To prevent next month''s attendance from misrouting this month''s contacts',
    'Event-specific tags like WS-2026-11-Attended prevent misrouting. If you reuse a generic Attended tag, next month''s attendees could trigger this month''s follow-up workflows incorrectly.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What trigger should apply the attended tag for in-person events?', 
    '["Event Registration","Form Submitted","Contact Created","Event Checked In"]'::jsonb,
    'Event Checked In',
    'Event Checked In is the appropriate trigger for in-person attendance. This fires when someone is checked in at the event, distinguishing actual attendees from mere registrants.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do when duplicating workflows for repeat events?', 
    '["Assume all references update automatically","Keep the same tags and filters to save time","Update tag names, event filters, and verify all references manually","Delete the old workflow before duplicating"]'::jsonb,
    'Update tag names, event filters, and verify all references manually',
    'Never assume cloned workflows update every reference automatically. Manually update tag names, event filters, and all references to ensure the new workflow targets the correct event.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

