-- Insert Quiz Questions for Lesson: Record Real Attendance

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 23 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 23 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm23-record-real-attendance' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m23-record-real-attendance not found in module 23';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Does registration prove that someone attended?', 
    '["Yes, if they clicked the calendar link","Only for paid events","No, registration is an intention, not attendance evidence","Yes, registration is sufficient evidence of attendance"]'::jsonb,
    'No, registration is an intention, not attendance evidence',
    'Registration is an intention, not proof of attendance. Many people register but do not join. Always verify attendance through check-in or platform reports before applying attended tags.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before launching post-event follow-up?', 
    '["Launch immediately after the event ends","Wait until attendance reports are available and reviewed","Send the same message to everyone regardless of attendance","Assume everyone who registered attended"]'::jsonb,
    'Wait until attendance reports are available and reviewed',
    'Hold post-event branching until attendance reports are available. Telling a real attendee Sorry we missed you because data arrived late is embarrassing and damages trust.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How should you handle online attendance for webinars?', 
    '["Only track attendance for in-person events","Assume all registrants attended","Use the registration time as attendance proof","Check platform attendance reports and apply tags manually or via tested integration"]'::jsonb,
    'Check platform attendance reports and apply tags manually or via tested integration',
    'For online events, check Zoom or meeting-platform attendance reports. Verify who actually participated, then apply the attended tag manually or through a tested integration.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

