-- Insert Quiz Questions for Lesson: Follow Up with the Right Message

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 23 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 23 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm23-follow-up-right-message' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m23-follow-up-right-message not found in module 23';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should an attendee follow-up email include?', 
    '["A demand to book immediately or lose the opportunity","Thanks, useful resources, and a relevant booking link","An apology for taking their time","A request to refer friends who did not attend"]'::jsonb,
    'Thanks, useful resources, and a relevant booking link',
    'Attendees should receive thanks, useful resources they can act on, and a relevant booking link connected to the event content. This feels like a natural next step, not a sales pitch.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should a no-show follow-up email include?', 
    '["A demand to explain why they did not attend","Guilt about missing the event and pressure to book","Understanding, replay or next date, and an optional booking link","Nothing — no-shows are not worth following up"]'::jsonb,
    'Understanding, replay or next date, and an optional booking link',
    'No-shows should receive understanding, a replay or next session date, and an optional booking link. Life happens; gracious follow-up keeps the door open for future engagement.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How do you ensure contacts do not receive both attended and no-show messages?', 
    '["Send both messages to everyone to be safe","Manually remove contacts from one list","Only send messages to attendees","Use exclusive If/Else branches based on the attended tag"]'::jsonb,
    'Use exclusive If/Else branches based on the attended tag',
    'Use If/Else based on the event-specific attended tag. The yes path sends attendee content; the no path sends no-show content. Confirm branches are exclusive so no contact receives both.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

